using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;

namespace Horizon {
 public sealed class SavedPreset {public string Id{get;set;}public string Name{get;set;}public Dictionary<string,double> Values{get;set;}}
 public sealed class PresetSelection {public string CustomId{get;set;}public string BuiltIn{get;set;}public List<string> KnownKeys{get;set;}}
 public sealed class PresetData {public int Format{get;set;}=1;public List<SavedPreset> Custom{get;set;}=new List<SavedPreset>();public Dictionary<string,PresetSelection> Clients{get;set;}=new Dictionary<string,PresetSelection>(StringComparer.OrdinalIgnoreCase);}
 public sealed class PresetStore {
  readonly string path;PresetData data;
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=4000000};}
  public PresetStore(string stateRoot){path=Path.Combine(stateRoot,"presets.json");SetupService.CheckDirectorySafety(stateRoot);if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0||new FileInfo(path).Length>4000000)throw new IOException("The saved preset file cannot be read safely.");try{data=Json().Deserialize<PresetData>(File.ReadAllText(path));Validate(data);}catch(Exception ex){throw new IOException("Saved presets could not be read. The original file has been preserved: "+path,ex);}}else data=new PresetData();}
  static void Validate(PresetData d){if(d==null||d.Format!=1||d.Custom==null||d.Clients==null||d.Custom.Count>256||d.Clients.Count>256)throw new IOException("Unsupported preset file.");var ids=new HashSet<string>();var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var p in d.Custom){Guid id;if(p==null||!Guid.TryParseExact(p.Id,"N",out id)||!ids.Add(p.Id)||!names.Add(Name(p.Name))||p.Values==null||p.Values.Count>12000||p.Values.Any(v=>double.IsNaN(v.Value)||double.IsInfinity(v.Value)))throw new IOException("Invalid saved preset.");}foreach(var c in d.Clients)if(c.Value==null||c.Value.KnownKeys==null||c.Value.KnownKeys.Count>12000)throw new IOException("Invalid preset selection.");d.Clients=new Dictionary<string,PresetSelection>(d.Clients,StringComparer.OrdinalIgnoreCase);}
  static string Name(string name){name=(name??"").Trim();if(name.Length<1||name.Length>60||name.Any(char.IsControl))throw new ArgumentException("Enter a preset name between 1 and 60 characters.");return name;}
  static string ClientKey(string client){return Path.GetFullPath(client).TrimEnd(Path.DirectorySeparatorChar);}
  void Update(Action<PresetData> change){var next=Json().Deserialize<PresetData>(Json().Serialize(data));next.Clients=new Dictionary<string,PresetSelection>(next.Clients,StringComparer.OrdinalIgnoreCase);change(next);Validate(next);string text=Json().Serialize(next);if(text.Length>4000000)throw new IOException("The preset collection is full.");SetupService.CheckDirectorySafety(Path.GetDirectoryName(path));string temporary=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var output=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var bytes=new UTF8Encoding(false).GetBytes(text);output.Write(bytes,0,bytes.Length);output.Flush(true);}if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("The saved preset file is a link.");File.Replace(temporary,path,path+".backup",true);}else File.Move(temporary,path);data=next;}finally{if(File.Exists(temporary))File.Delete(temporary);}}
  public List<Preset> Choices(Catalog catalog){return catalog.presets.Concat(data.Custom.OrderBy(p=>p.Name,StringComparer.OrdinalIgnoreCase).Select(p=>new Preset{name=p.Name,customId=p.Id,values=new Dictionary<string,double>(p.Values,StringComparer.OrdinalIgnoreCase)})).ToList();}
  public PresetSelection Selection(string client){PresetSelection selection;return data.Clients.TryGetValue(ClientKey(client),out selection)?selection:null;}
  public SavedPreset ActiveCustom(string client){var s=Selection(client);return s==null?null:data.Custom.FirstOrDefault(p=>p.Id==s.CustomId);}
  public HashSet<string> Missing(string client,Catalog catalog){var custom=ActiveCustom(client);return new HashSet<string>(custom==null?Enumerable.Empty<string>():catalog.settings.Where(s=>!custom.Values.ContainsKey(s.key)).Select(s=>s.key),StringComparer.OrdinalIgnoreCase);}
  public Dictionary<string,double> Values(Preset preset,Catalog catalog){var result=new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase);foreach(var s in catalog.settings){double value;if(preset.values.TryGetValue(s.key,out value))result[s.key]=s.Normalize(value);}return result;}
  public void Select(string client,Preset preset,Catalog catalog){Update(d=>d.Clients[ClientKey(client)]=new PresetSelection{CustomId=preset.customId,BuiltIn=string.IsNullOrEmpty(preset.customId)?preset.name:null,KnownKeys=catalog.settings.Select(s=>s.key).ToList()});}
  public Dictionary<string,double> NewBuiltInValues(string client,Catalog catalog){var selection=Selection(client);var result=new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase);if(selection==null||!string.IsNullOrEmpty(selection.CustomId))return result;var preset=catalog.presets.FirstOrDefault(p=>p.name==selection.BuiltIn);if(preset==null)return result;var known=new HashSet<string>(selection.KnownKeys,StringComparer.OrdinalIgnoreCase);foreach(var s in catalog.settings.Where(s=>!known.Contains(s.key))){double value;result[s.key]=s.Normalize(preset.values.TryGetValue(s.key,out value)?value:s.defaultValue);}return result;}
  public void AcknowledgeBuiltIn(string client,Catalog catalog){var s=Selection(client);if(s==null||!string.IsNullOrEmpty(s.CustomId))return;Update(d=>d.Clients[ClientKey(client)].KnownKeys=catalog.settings.Select(x=>x.key).ToList());}
  public void RecordEdits(string client,IDictionary<string,double> values){var p=ActiveCustom(client);if(p==null)return;Update(d=>{var target=d.Custom.Single(x=>x.Id==p.Id);foreach(var v in values)target.Values[v.Key]=v.Value;});}
  public Preset SaveNamed(string client,string name,Catalog catalog){name=Name(name);if(catalog.presets.Any(p=>string.Equals(p.name,name,StringComparison.OrdinalIgnoreCase)))throw new ArgumentException("Choose a name different from a built-in preset.");var active=ActiveCustom(client);var existing=data.Custom.FirstOrDefault(p=>string.Equals(p.Name,name,StringComparison.OrdinalIgnoreCase));if(existing!=null&&(active==null||existing.Id!=active.Id))throw new ArgumentException("That preset name already exists. Choose another name, or apply it before saving changes.");var missing=Missing(client,catalog);var values=catalog.settings.Where(s=>!missing.Contains(s.key)).ToDictionary(s=>s.key,s=>s.Normalize(s.Value),StringComparer.OrdinalIgnoreCase);string id=existing==null?Guid.NewGuid().ToString("N"):existing.Id;Update(d=>{var target=d.Custom.FirstOrDefault(p=>p.Id==id);if(target==null){target=new SavedPreset{Id=id};d.Custom.Add(target);}target.Name=name;target.Values=values;d.Clients[ClientKey(client)]=new PresetSelection{CustomId=id,KnownKeys=catalog.settings.Select(s=>s.key).ToList()};});return new Preset{name=name,customId=id,values=values};}
 }
}
